DO $$ DECLARE role_name text; t text; f record; BEGIN
 FOREACH t IN ARRAY ARRAY['centre_session_authors','centre_note_consents'] LOOP
 PERFORM pg_temp.team_check((SELECT relrowsecurity FROM pg_class WHERE oid=('pc_private.'||t)::regclass),'private metadata RLS');
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
 PERFORM pg_temp.team_check(NOT has_table_privilege(role_name,'pc_private.'||t,'SELECT,INSERT,UPDATE,DELETE'),'private metadata denied');END LOOP; END LOOP;
 FOR f IN SELECT oid::regprocedure signature,prosecdef,proconfig FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('set_centre_note_permission','get_centre_lesson_note_context','record_centre_lesson_note','revise_centre_lesson_note','list_my_centre_note_revisions','withdraw_my_centre_note_consent','list_professional_note_revisions_v2') LOOP
 PERFORM pg_temp.team_check(NOT f.prosecdef,'public invoker only');
 PERFORM pg_temp.team_check(NOT has_function_privilege('anon',f.signature,'EXECUTE') AND NOT has_function_privilege('service_role',f.signature,'EXECUTE'),'RPC denied to anonymous and service role');END LOOP;
 PERFORM pg_temp.team_check(NOT has_function_privilege('authenticated','pc_private.centre_note_access(uuid,uuid,uuid,uuid)','EXECUTE'),'helper unavailable');
END $$;
